/* ===== Admin console (Oct 2026), like Pentra Tindahan: approve (confirm) or reject payments, add or remove days, pause, remove,
   give access by email, history and settings. Only admins see it; the server checks every action again. ===== */
var Admin = (function(){
  var tab = 'pay', data = {}, q = '', filt = 'pending', busy = false;
  var TABS = [['pay', 'Payments'], ['subs', 'Subscribers'], ['give', 'Give access'], ['hist', 'History'], ['set', 'Settings']];
  function day(t){ try { return t ? new Date(t).toLocaleString('en-PH', { month:'short', day:'numeric', year:'numeric', hour:'numeric', minute:'2-digit' }) : '\u2014'; } catch (e) { return ''; } }
  function stateOf(s){ var now = Date.now(), end = new Date(s.access_ends_at || 0).getTime(); return s.removed ? 'Removed' : s.paused ? 'Paused' : (s.paid_until && new Date(s.paid_until).getTime() > now) ? 'Active' : (new Date(s.trial_ends_at).getTime() > now) ? 'Trial' : end > now ? 'Pending' : 'Locked'; }
  function load(){ busy = true; paint(); var calls = { pay:function(){ return Cloud.rpc('admin_payments', { p_status:filt }).then(function(d){ data.pay = d; }); }, subs:function(){ return Cloud.rpc('admin_subscribers', { p_search:q || null }).then(function(d){ data.subs = d; }); },
      give:function(){ return Cloud.rpc('admin_grants').then(function(d){ data.grants = d; }); }, hist:function(){ return Cloud.rpc('admin_history', { p_limit:200 }).then(function(d){ data.hist = d; }); }, set:function(){ return Cloud.rpc('admin_settings', { p_set:null }).then(function(d){ data.set = d; }); } };
    return calls[tab]().then(function(){ data.err = ''; }).catch(function(e){ data.err = e.message; }).then(function(){ busy = false; paint(); }); }
  function ask(o){ return new Promise(function(res){ var ov = document.createElement('div'); ov.className = 'lv-sheet'; ov.id = 'admAsk'; ov.setAttribute('role', 'dialog'); ov.setAttribute('aria-modal', 'true');
    ov.innerHTML = '<div><div class="lv-grab"></div><h2>' + esc(o.title) + '</h2><p class="hint">' + o.text + '</p>' + (o.input ? '<input class="lv-search" data-ask-in maxlength="200" placeholder="' + esc(o.input) + '" aria-label="' + esc(o.input) + '"><p class="hint" data-ask-err role="alert" style="color:var(--bad);min-height:1.2em"></p>' : '')
      + '<button type="button" class="lv-add" data-ask="ok" style="border-style:solid;background:' + (o.danger ? 'var(--bad)' : 'var(--accent)') + ';color:' + (o.danger ? '#fff' : 'var(--accent-ink)') + '">' + esc(o.ok) + '</button><button type="button" class="lv-add" data-ask="no">Cancel</button></div>';
    document.body.appendChild(ov); var inp = ov.querySelector('[data-ask-in]'); (inp || ov.querySelector('[data-ask="ok"]')).focus();
    ov.addEventListener('click', function(e){ var b = e.target.closest('[data-ask]'); if (e.target === ov || (b && b.getAttribute('data-ask') === 'no')) { ov.remove(); res(null); return; } if (!b) return;
      var v = inp ? inp.value.trim() : true; if (inp && o.required && !v) { ov.querySelector('[data-ask-err]').textContent = o.required; return; } ov.remove(); res(v); }); }); }
  function run(fn, args, done){ return Cloud.rpc(fn, args).then(function(){ toast(done, 'good'); return load(); }).catch(function(e){ toast(e.message, 'bad'); }); }
  function payCard(p){ return '<div class="card" style="margin:8px 0;padding:14px"><div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap"><b>' + esc(p.email || '') + '</b><span class="lv-tag ' + (p.status === 'pending' ? 'next' : p.status === 'approved' ? 'done' : 'cur') + '">' + esc(p.status.toUpperCase()) + '</span></div>'
    + '<div class="num" style="font-size:28px;margin:6px 0">' + Access.peso(p.amount) + ' \u00b7 ' + (p.plan === 'monthly' ? 'Monthly' : 'Yearly') + '</div><div>Reference <b style="font-family:monospace;font-size:16px">' + esc(p.reference) + '</b></div>'
    + (p.note ? '<div class="hint" style="margin:4px 0">Note: ' + esc(p.note) + '</div>' : '') + '<div class="hint" style="margin:4px 0">Sent ' + day(p.submitted_at) + (p.reason ? ' \u00b7 ' + esc(p.reason) : '') + '</div>'
    + (p.status === 'pending' ? '<div class="th-row"><button type="button" class="btn primary" data-ad="approve" data-id="' + p.id + '">Approve</button><button type="button" class="btn" data-ad="reject" data-id="' + p.id + '">Reject</button></div>' : '') + '</div>'; }
  function subCard(s){ var st = stateOf(s); return '<div class="card" style="margin:8px 0;padding:14px"><div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap"><b>' + esc(s.email || s.owner_id) + '</b><span class="lv-tag ' + (st === 'Active' ? 'done' : st === 'Trial' || st === 'Pending' ? 'next' : 'cur') + '">' + st.toUpperCase() + '</span></div>'
    + '<div class="hint" style="margin:4px 0">' + (s.paid_until ? 'Paid until ' + day(s.paid_until) : 'Trial until ' + day(s.trial_ends_at)) + (s.restricted ? ' \u00b7 payments on hold (' + s.rejected_count + ' rejected)' : '') + '</div>'
    + '<div class="th-row"><input type="number" min="1" max="3650" value="30" data-days="' + s.owner_id + '" aria-label="Days for ' + esc(s.email || '') + '" style="width:84px;min-height:44px;border-radius:10px;border:1px solid var(--border2);background:var(--surface2);color:var(--text);padding:0 8px">'
    + '<button type="button" class="btn" data-ad="add" data-id="' + s.owner_id + '">+ Add days</button><button type="button" class="btn" data-ad="sub" data-id="' + s.owner_id + '">\u2212 Remove days</button></div>'
    + '<div class="th-row"><button type="button" class="btn" data-ad="' + (s.paused ? 'resume' : 'pause') + '" data-id="' + s.owner_id + '">' + (s.paused ? 'Resume' : 'Pause') + '</button><button type="button" class="btn" data-ad="' + (s.removed ? 'restore' : 'remove') + '" data-id="' + s.owner_id + '">' + (s.removed ? 'Restore' : 'Remove') + '</button>'
    + (s.restricted ? '<button type="button" class="btn" data-ad="clear" data-id="' + s.owner_id + '">Clear hold</button>' : '') + '</div></div>'; }
  function inner(){ if (!Cloud.user()) return '<p class="hint">Sign in with your admin account first.</p><button type="button" class="btn primary" data-acct-open>Sign in</button>';
    if (!Access.isAdmin()) return '<p class="hint">Admins only.</p>';
    var h = '<div class="lv-chips" role="tablist" style="justify-content:flex-start">' + TABS.map(function(t){ return '<button type="button" class="lv-chip" role="tab" data-tab="' + t[0] + '" aria-pressed="' + (tab === t[0]) + '" aria-selected="' + (tab === t[0]) + '">' + t[1] + '</button>'; }).join('') + '</div>';
    if (data.err) h += '<p class="hint" role="alert" style="color:var(--bad)">' + esc(data.err) + '</p>'; if (busy) h += '<p class="hint">Loading\u2026</p>';
    if (tab === 'pay') h += '<div class="lv-chips" style="justify-content:flex-start"><button type="button" class="lv-chip" data-filt="pending" aria-pressed="' + (filt === 'pending') + '">Waiting</button><button type="button" class="lv-chip" data-filt="all" aria-pressed="' + (filt === 'all') + '">All</button></div>'
      + ((data.pay || []).map(payCard).join('') || (busy ? '' : '<p class="hint">No payments ' + (filt === 'pending' ? 'waiting' : 'yet') + '.</p>'));
    if (tab === 'subs') h += '<input class="lv-search" data-subq value="' + esc(q) + '" placeholder="Search by email" aria-label="Search subscribers">' + ((data.subs || []).map(subCard).join('') || (busy ? '' : '<p class="hint">No subscribers found.</p>'));
    if (tab === 'give') h += '<div class="card" style="padding:14px"><p class="hint" style="margin-top:0">Works even before the person signs up: it applies at their first sign-in.</p><input class="lv-search" data-g="email" type="email" placeholder="Email address" aria-label="Email address">'
      + '<select class="lv-search" data-g="plan" aria-label="Access to give"><option value="monthly">1 month</option><option value="yearly">1 year</option><option value="days">Number of days</option><option value="trial">Restart the free trial</option></select>'
      + '<input class="lv-search" data-g="days" type="number" min="1" max="3650" placeholder="Days (for Number of days)" aria-label="Days"><label class="th-row"><input type="checkbox" data-g="cash" style="width:22px;height:22px"> Also record a cash payment (1 month or 1 year)</label>'
      + '<input class="lv-search" data-g="note" maxlength="200" placeholder="Note (optional)" aria-label="Note"><button type="button" class="btn primary" data-ad="give">Give access</button></div>'
      + '<h3 style="margin:14px 0 4px">Waiting to be used</h3>' + ((data.grants || []).map(function(g){ return '<div class="card" style="margin:8px 0;padding:12px;display:flex;justify-content:space-between;gap:8px;align-items:center;flex-wrap:wrap"><span><b>' + esc(g.email) + '</b> \u00b7 ' + esc(g.plan === 'days' ? g.days + ' days' : g.plan) + '</span><button type="button" class="btn" data-ad="cancel" data-id="' + g.id + '">Cancel</button></div>'; }).join('') || '<p class="hint">None.</p>');
    if (tab === 'hist') h += (data.hist || []).map(function(x){ return '<div style="padding:10px 0;border-bottom:1px solid var(--border)"><b>' + esc(x.action) + '</b> \u00b7 ' + esc(x.subscriber || '') + '<br><span class="hint">' + day(x.at) + (x.admin ? ' \u00b7 by ' + esc(x.admin) : '') + (x.detail && x.detail.reason ? ' \u00b7 ' + esc(x.detail.reason) : '') + '</span></div>'; }).join('') || '<p class="hint">Nothing yet.</p>';
    if (tab === 'set' && data.set) { var c = data.set; h += '<div class="card" style="padding:14px"><label class="th-row"><input type="checkbox" data-s="enabled"' + (c.enabled ? ' checked' : '') + ' style="width:22px;height:22px"> <b>Payments switched on</b></label><p class="hint">While off, everyone can use everything for free.</p>'
      + [['trial_days', 'Free trial (days)', c.trial_days], ['price_monthly', 'Monthly price (\u20B1)', c.price_monthly / 100], ['price_yearly', 'Yearly price (\u20B1)', c.price_yearly / 100], ['pending_hours', 'Access while a payment waits (hours)', c.pending_hours], ['offline_days', 'Offline grace (days)', c.offline_days]].map(function(f){ return '<label style="display:block;margin:8px 0">' + f[1] + '<input class="lv-search" type="number" data-s="' + f[0] + '" value="' + f[2] + '"></label>'; }).join('')
      + '<label style="display:block;margin:8px 0">Help email<input class="lv-search" type="email" data-s="help_email" value="' + esc(c.help_email) + '"></label><p class="hint" style="color:var(--warn)">The QR codes are fixed at \u20B1129 and \u20B11,199. Change prices only together with new QR codes.</p><button type="button" class="btn primary" data-ad="save-set">Save settings</button></div>'; }
    return h; }
  function paint(){ var v = document.querySelector('#view [data-admin]'); if (v) v.innerHTML = inner(); }
  function render(v){ v.innerHTML = '<div class="page-head"><h1>Admin</h1><p class="sub">Subscriptions and payments</p></div><div data-admin></div>'; paint(); if (Cloud.user() && Access.isAdmin()) load(); }
  document.addEventListener('click', function(e){ var t = e.target.closest('[data-tab]'); if (t && document.querySelector('[data-admin]')) { tab = t.getAttribute('data-tab'); load(); return; }
    var f = e.target.closest('[data-filt]'); if (f) { filt = f.getAttribute('data-filt'); load(); return; }
    var b = e.target.closest('[data-ad]'); if (!b || !document.querySelector('[data-admin]')) return; var a = b.getAttribute('data-ad'), id = b.getAttribute('data-id'), p = (data.pay || []).filter(function(x){ return x.id === id; })[0];
    if (a === 'approve') ask({ title:'Approve payment?', text:'Confirm you received <b>' + Access.peso(p.amount) + '</b> with reference <b>' + esc(p.reference) + '</b> from ' + esc(p.email || '') + '. This adds ' + (p.plan === 'monthly' ? '30' : '365') + ' days.', ok:'Yes, I received it' }).then(function(ok){ if (ok) run('admin_review', { p_id:id, p_approve:true, p_reason:null }, 'Payment approved.'); });
    else if (a === 'reject') ask({ title:'Reject payment?', text:'Tell ' + esc(p.email || 'the subscriber') + ' why. They will see this.', input:'Reason (e.g. amount did not match)', required:'Write the reason first.', ok:'Reject payment', danger:true }).then(function(r){ if (r) run('admin_review', { p_id:id, p_approve:false, p_reason:r }, 'Payment rejected.'); });
    else if (a === 'add' || a === 'sub') { var n = Math.round(+((document.querySelector('[data-days="' + id + '"]') || {}).value || 0)); if (!(n >= 1 && n <= 3650)) { toast('Enter 1 to 3650 days.', 'bad'); return; } run('admin_update', { p_owner:id, p_days:a === 'add' ? n : -n, p_clear_restriction:false, p_reason:null }, (a === 'add' ? 'Added ' : 'Removed ') + n + ' days.'); }
    else if (a === 'pause' || a === 'resume') run('admin_pause', { p_owner:id, p_on:a === 'pause', p_note:null }, a === 'pause' ? 'Paused.' : 'Resumed.');
    else if (a === 'remove') ask({ title:'Remove subscriber?', text:'They lose access until you restore them. Their data is kept.', ok:'Remove', danger:true }).then(function(ok){ if (ok) run('admin_remove', { p_owner:id, p_restore:false, p_note:null }, 'Removed.'); });
    else if (a === 'restore') run('admin_remove', { p_owner:id, p_restore:true, p_note:null }, 'Restored.');
    else if (a === 'clear') run('admin_update', { p_owner:id, p_days:0, p_clear_restriction:true, p_reason:null }, 'Hold cleared.');
    else if (a === 'cancel') run('admin_cancel_grant', { p_id:id }, 'Cancelled.');
    else if (a === 'give') { var g = function(k){ return document.querySelector('[data-g="' + k + '"]'); }, plan = g('plan').value, days = Math.round(+g('days').value || 0);
      run('admin_add', { p_email:g('email').value.trim(), p_plan:plan, p_days:plan === 'days' ? days : null, p_record_payment:g('cash').checked, p_amount:null, p_note:g('note').value }, 'Access given.'); }
    else if (a === 'save-set') { var s = function(k){ return document.querySelector('[data-s="' + k + '"]'); }, on = s('enabled').checked, set = { enabled:on, trial_days:+s('trial_days').value, price_monthly:Math.round(+s('price_monthly').value * 100), price_yearly:Math.round(+s('price_yearly').value * 100), pending_hours:+s('pending_hours').value, offline_days:+s('offline_days').value, help_email:s('help_email').value.trim() };
      var go = function(){ run('admin_settings', { p_set:set }, 'Settings saved.').then(function(){ Access.refresh(); }); };
      if (data.set && on && !data.set.enabled) ask({ title:'Switch payments on?', text:'Trials start counting and people without time left can no longer log new workouts.', ok:'Switch on' }).then(function(ok){ if (ok) go(); }); else go(); } });
  document.addEventListener('input', function(e){ if (e.target.hasAttribute('data-subq')) { q = e.target.value; clearTimeout(Admin._t); Admin._t = setTimeout(load, 400); } });
  function init(){ var ex = ROUTES.filter(function(r){ return r.id === 'admin'; })[0]; if (ex) { ex.render = render; delete ex._stub; } else ROUTES.push({ id:'admin', label:'Admin', icon:'', render:render }); if (currentRoute() === 'admin') router(); }
  Cloud.on(function(){ if (document.querySelector('[data-admin]')) setTimeout(function(){ Access.refresh().then(function(){ var v = document.getElementById('view'); if (v && currentRoute() === 'admin') render(v); }); }, 0); });
  return { init:init, load:load };
})();

/* ===== Free tools (Oct 2026): 1RM + %1RM table, TDEE (Mifflin–St Jeor), protein, macros, body fat (U.S. Navy tape), plates. Prefilled from your data. ===== */
