/* ===== Season report (Oct 2026, Build 18): one printable page for a training block — workouts, volume, PRs, Forge rank climb, lift progress,
   weekly volume, body changes, adherence, achievements. "Print / Save as PDF" uses the browser; print layout is light. ===== */
var Report = (function(){
  var days = 84, DAY = 864e5, RANGES = [[28, 'Last 4 weeks'], [84, 'Last 12 weeks'], [0, 'All time']];
  function t(d){ return new Date(d + 'T12:00:00').getTime(); }
  function kg(x){ return fmtNum(Math.round(dispW(x) * 10) / 10) + ' ' + unitW(); }
  function data(){ var now = t(todayISO()), from = days ? now - (days - 1) * DAY : -Infinity, all = S.sessions.slice().sort(function(a, b){ return String(a.date).localeCompare(String(b.date)); }), ses = all.filter(function(s){ return t(s.date) >= from; });
    var sets = 0, vol = 0; ses.forEach(function(s){ (s.sets || []).forEach(function(x){ if (x.type === 'warmup' || !(x.reps > 0)) return; sets++; vol += (+x.load || 0) * x.reps; }); });
    var start = ses.length ? ses[0].date : null, span = days || (start ? Math.max(7, Math.round((now - t(start)) / DAY) + 1) : 7), prs = window.History ? History.events().filter(function(e){ return t(e.date) >= from; }).length : 0;
    var H = Ranks.history(), inR = H.filter(function(h){ return t(h.date) >= from; }), before = H.filter(function(h){ return t(h.date) < from; }), r0 = before.length ? before[before.length - 1] : inR[0], r1 = H.length ? H[H.length - 1] : null;
    var lifts = Ranks.lifts().map(function(l){ var b0 = 0; all.forEach(function(s){ if (t(s.date) >= from) return; (s.sets || []).forEach(function(x){ if (x.exercise === l.name && x.type !== 'warmup' && x.reps > 0 && x.reps <= 12) b0 = Math.max(b0, e1rm(x.load, x.reps)); }); });
      if (!b0) ses.slice(0, 1).forEach(function(s){ (s.sets || []).forEach(function(x){ if (x.exercise === l.name && x.type !== 'warmup' && x.reps > 0 && x.reps <= 12) b0 = Math.max(b0, e1rm(x.load, x.reps)); }); }); return { name:l.name, lift:l.lift, from:b0 || l.e1, to:l.e1, div:l.div }; });
    var nW = Math.min(12, Math.ceil(span / 7)), mon = new Date(todayISO() + 'T12:00:00'); mon.setDate(mon.getDate() - ((mon.getDay() + 6) % 7)); var weeks = [];
    for (var w = nW - 1; w >= 0; w--) { var a = mon.getTime() - 7 * w * DAY, b = a + 7 * DAY, v = 0; ses.forEach(function(s){ var x = t(s.date); if (x >= a && x < b) (s.sets || []).forEach(function(y){ if (y.type !== 'warmup' && y.reps > 0) v += (+y.load || 0) * y.reps; }); }); weeks.push(v); }
    var body = (S.body || []).filter(function(r){ return r.date && t(r.date) >= from && +r.weight > 0; }).sort(function(a, b){ return String(a.date).localeCompare(String(b.date)); });
    var ach = window.Achieve ? Achieve.list() : [];
    return { workouts:ses.length, sets:sets, vol:vol, prs:prs, perWeek:Math.round(ses.length / (span / 7) * 10) / 10, start:start, r0:r0, r1:r1, lifts:lifts, weeks:weeks, w0:body[0], w1:body[body.length - 1], ach:[ach.filter(function(a){ return a.done; }).length, ach.length], strict:window.Arena ? Arena.strict().rate : null }; }
  function bars(W){ var mx = Math.max.apply(null, W.concat([1])), bw = 300 / W.length; return '<svg class="rp-bars" viewBox="0 0 300 110" role="img" aria-label="Weekly volume, ' + W.length + ' weeks, highest ' + kg(mx) + '">' + W.map(function(v, i){ var h = Math.round(v / mx * 90); return '<rect x="' + (i * bw + 3).toFixed(1) + '" y="' + (100 - h) + '" width="' + (bw - 6).toFixed(1) + '" height="' + Math.max(h, 1) + '" rx="3" fill="var(--rp-accent)"/>'; }).join('') + '<line x1="0" y1="100.5" x2="300" y2="100.5" stroke="currentColor" stroke-opacity=".3"/></svg>'; }
  function view(){ var d = data(), rk = function(r){ return r ? Ranks.badge(Ranks.tierOf(r.rating), 56) + '<span><b>' + esc(Ranks.div(r.rating).label) + '</b><small>rating ' + r.rating + '</small></span>' : '<span><b>Not ranked</b></span>'; };
    return '<div class="page-head"><h1>Season report</h1><p class="sub">Your training block on one page \u2014 print it or save it as a PDF</p></div><div class="rp-tools"><div class="lv-chips" role="group" aria-label="Report period">' + RANGES.map(function(r){ return '<button type="button" class="lv-chip" data-rp-range="' + r[0] + '" aria-pressed="' + (days === r[0]) + '">' + r[1] + '</button>'; }).join('') + '</div><button type="button" class="btn primary" data-rp-print>Print / Save as PDF</button></div>'
      + '<article class="rp-sheet card"><header class="rp-head"><div><small>' + esc(String(S.app.appName || 'Pentra Forge').toUpperCase()) + ' \u00b7 SEASON REPORT</small><h2>' + esc((RANGES.filter(function(r){ return r[0] === days; })[0] || RANGES[1])[1]) + '</h2><small>' + (d.start ? esc(d.start) + ' \u2192 ' + esc(todayISO()) : 'No workouts in this period yet') + ' \u00b7 ' + esc(S.program.name || '') + '</small></div></header>'
      + '<div class="rp-stats">' + [['Workouts', fmtNum(d.workouts)], ['Per week', fmtNum(d.perWeek)], ['Working sets', fmtNum(d.sets)], ['Volume', fmtNum(Math.round(dispW(d.vol))) + ' ' + unitW()], ['New PRs', fmtNum(d.prs)], ['Strict rate', d.strict != null ? d.strict + '%' : '\u2014']].map(function(s){ return '<div><b>' + s[1] + '</b><small>' + s[0] + '</small></div>'; }).join('') + '</div>'
      + '<section><h3>Forge rank</h3><div class="rp-rank"><div>' + rk(d.r0) + '</div><span class="rp-arrow" aria-hidden="true">\u2192</span><div>' + rk(d.r1) + '</div></div></section>'
      + '<section><h3>Ranked lifts</h3>' + (d.lifts.length ? '<table class="rp-t"><thead><tr><th scope="col">Lift</th><th scope="col">Start e1RM</th><th scope="col">Now</th><th scope="col">Change</th><th scope="col">Rank</th></tr></thead><tbody>' + d.lifts.map(function(l){ var ch = l.to - l.from; return '<tr><td>' + esc(l.name) + '</td><td>' + kg(l.from) + '</td><td>' + kg(l.to) + '</td><td class="' + (ch > 0 ? 'up' : '') + '">' + (ch > 0 ? '+' : '') + fmtNum(Math.round(dispW(ch) * 10) / 10) + '</td><td>' + (l.div ? esc(l.div.label) : '\u2014') + '</td></tr>'; }).join('') + '</tbody></table>' : '<p class="hint">No ranked lifts logged yet.</p>') + '</section>'
      + '<section><h3>Weekly volume</h3>' + bars(d.weeks) + '</section>'
      + '<section class="rp-two"><div><h3>Body</h3>' + (d.w0 && d.w1 ? '<p>Bodyweight ' + kg(+d.w0.weight) + ' \u2192 ' + kg(+d.w1.weight) + ' (' + (d.w1.weight - d.w0.weight >= 0 ? '+' : '') + fmtNum(Math.round(dispW(d.w1.weight - d.w0.weight) * 10) / 10) + ')</p>' : '<p class="hint">No bodyweight logged in this period.</p>') + '</div><div><h3>Achievements</h3><p>' + d.ach[0] + ' of ' + d.ach[1] + ' unlocked</p></div></section>'
      + '<footer class="rp-foot">Ranks use DOTS with lift shares on estimated 1RMs from sets of 12 reps or fewer. Generated ' + esc(todayISO()) + '.</footer></article>'; }
  function render(v){ v.innerHTML = view(); }
  document.addEventListener('click', function(e){ var r = e.target.closest('[data-rp-range]'); if (r) { days = +r.getAttribute('data-rp-range'); var v = document.getElementById('view'); if (v && currentRoute() === 'report') { render(v); var b = document.querySelector('[data-rp-range="' + days + '"]'); if (b) b.focus(); } return; } if (e.target.closest('[data-rp-print]')) window.print(); });
  (typeof registerRoute === 'function' ? registerRoute : function(d){ if (!ROUTES.some(function(r){ return r.id === d.id; })) ROUTES.push(d); })({ id:'report', label:'Season report', icon:(typeof ICON !== 'undefined' && (ICON.goals || ICON.strength)) || '', render:render });
  return { data:data, set:function(n){ days = n; } };
})();
